  `),$s=["// Resonant Lab — esquisse Arduino pour Teensy 4.1","// Une banque logicielle additive remplace les générateurs matériels séparés.","// Cible : Arduino IDE + Teensyduino, Teensy 4.1, Audio Shield Rev D/D2, USB MIDI Host.","// Ce prototype ne porte pas encore les filtres, saturations ni le bruit du patch.","#include <Audio.h>","#include <USBHost_t36.h>","#include <math.h>","","static const uint32_t kSampleRate = 44100;","static const uint16_t kTableSize = 1024;","static const uint8_t kVoiceCount = 8;","static const uint8_t kPartialCount = "+Fa.length+";","static const uint8_t kReferenceMidi = "+mi+";","static const float kAttackSeconds = "+Bg(Ga)+";","static const float kReleaseSeconds = "+Bg(Li)+";","static const float kPartialData[][4] = {","  // fréquence Hz, amplitude relative, tau de décroissance s, phase en cycles","  "+ms,"};","","float sineTable[kTableSize];","USBHost usbHost;","MIDIDevice_BigBuffer usbMidi(usbHost);","","class ResonantAdditiveBank : public AudioStream {","  struct Voice { bool active=false; bool released=false; uint8_t note=0; uint32_t age=0; float velocity=0; float pitch=1; float attack=0; float release=1; float phase[kPartialCount]{}; float decay[kPartialCount]{}; };","  Voice voices[kVoiceCount]; float decayStep[kPartialCount]; uint32_t serial=0; float releaseStep=1; float norm=1;","public:","  ResonantAdditiveBank() : AudioStream(0, nullptr) {}","  void begin() {","    for (uint16_t i=0;i<kTableSize;i++) sineTable[i]=sinf(6.28318530718f*(float)i/(float)kTableSize);","    float sum=0; for(uint8_t p=0;p<kPartialCount;p++) sum+=fabsf(kPartialData[p][1]);","    norm=sum>0 ? 0.82f/sum : 0.0f;","    for(uint8_t p=0;p<kPartialCount;p++){const float tau=fmaxf(kPartialData[p][2],0.0001f);decayStep[p]=expf(-1.0f/(tau*(float)kSampleRate));}","    const float r=fmaxf(kReleaseSeconds,0.005f); releaseStep=expf(-1.0f/(r*(float)kSampleRate));","  }","  void noteOn(uint8_t note,uint8_t velocity) {","    Voice *v=nullptr; for(uint8_t i=0;i<kVoiceCount;i++) if(voices[i].active&&voices[i].note==note){v=&voices[i];break;}","    if(!v) for(uint8_t i=0;i<kVoiceCount;i++) if(!voices[i].active){v=&voices[i];break;}","    if(!v){v=&voices[0];for(uint8_t i=1;i<kVoiceCount;i++) if(voices[i].age<v->age) v=&voices[i];}","    v->active=true;v->released=false;v->note=note;v->age=++serial;v->pitch=powf(2.0f,((int)note-(int)kReferenceMidi)/12.0f);v->velocity=powf((float)velocity/127.0f,1.5f);v->attack=0;v->release=1;","    for(uint8_t p=0;p<kPartialCount;p++){v->phase[p]=kPartialData[p][3];v->phase[p]-=floorf(v->phase[p]);v->decay[p]=1.0f;}","  }","  void noteOff(uint8_t note) { for(uint8_t i=0;i<kVoiceCount;i++) if(voices[i].active&&voices[i].note==note) voices[i].released=true; }","  void update() override {","    audio_block_t *block=allocate(); if(!block)return;","    const float attackStep=kAttackSeconds>0 ? 1.0f/(kAttackSeconds*(float)kSampleRate) : 1.0f;","    for(uint16_t n=0;n<AUDIO_BLOCK_SAMPLES;n++){","      float mix=0.0f;uint8_t activeVoices=0;","      for(uint8_t vIndex=0;vIndex<kVoiceCount;vIndex++){Voice &v=voices[vIndex];if(!v.active)continue;","        if(v.released){v.release*=releaseStep;if(v.release<0.0001f){v.active=false;continue;}}else if(v.attack<1.0f){v.attack=fminf(1.0f,v.attack+attackStep);}","        activeVoices++;","        for(uint8_t p=0;p<kPartialCount;p++){const float hz=kPartialData[p][0]*v.pitch;if(hz<=0.0f||hz>=0.49f*(float)kSampleRate)continue;","          const float x=v.phase[p]*(float)kTableSize;const uint16_t i=(uint16_t)x;const float frac=x-(float)i;","          const float s=sineTable[i]*(1.0f-frac)+sineTable[(i+1)&(kTableSize-1)]*frac;","          mix+=s*kPartialData[p][1]*v.decay[p]*v.attack*v.release*v.velocity*norm;","          v.phase[p]+=hz/(float)kSampleRate;if(v.phase[p]>=1.0f)v.phase[p]-=1.0f;","          v.decay[p]*=decayStep[p];","        }","      }","      if(activeVoices)mix/=(float)activeVoices;mix=fmaxf(-0.98f,fminf(0.98f,mix));block->data[n]=(int16_t)lrintf(mix*32767.0f);","    }","    transmit(block);release(block);","  }","};","","ResonantAdditiveBank synth;","AudioControlSGTL5000 audioControl;","AudioOutputI2S i2sOut;","AudioConnection leftLink(synth,0,i2sOut,0);","AudioConnection rightLink(synth,0,i2sOut,1);","","void onNoteOn(byte channel,byte note,byte velocity);","void onNoteOff(byte channel,byte note,byte velocity);","void onNoteOn(byte channel,byte note,byte velocity){(void)channel;if(!velocity){onNoteOff(channel,note,0);return;}AudioNoInterrupts();synth.noteOn(note,velocity);AudioInterrupts();}","void onNoteOff(byte channel,byte note,byte velocity){(void)channel;(void)velocity;AudioNoInterrupts();synth.noteOff(note);AudioInterrupts();}","","void setup(){","  AudioMemory(16);","  synth.begin();","  audioControl.enable();","  audioControl.volume(0.30f); // niveau casque prudent au premier branchement","  usbHost.begin();","  usbMidi.setHandleNoteOn(onNoteOn);","  usbMidi.setHandleNoteOff(onNoteOff);","}","void loop(){usbHost.Task();usbMidi.read();}",""].join(`
